-- 03-code-graph.sql
--
-- EXTRACTED VERBATIM from artifacts/v1/gaos-arcadedb-model.html, which is the
-- source of truth for this schema. Do not edit this file to change the model:
-- change the document, then re-extract. A deviation that lives only here is a
-- schema nobody reviewing the model document would ever see.
--
-- Applied in filename order by deploy/schema/apply.sh. Every statement carries
-- IF NOT EXISTS, so applying twice is a no-op rather than an error.

-- Written by the indexer. Volume here is 10-100x the rest of the model,
-- so File and Function get multiple buckets for insert concurrency.

CREATE VERTEX TYPE Repository IF NOT EXISTS EXTENDS GaosVertex;
CREATE PROPERTY Repository.name          STRING (mandatory true, notnull true);
CREATE PROPERTY Repository.url           STRING;
CREATE PROPERTY Repository.defaultBranch STRING (default 'main');
CREATE PROPERTY Repository.language      STRING;
CREATE PROPERTY Repository.indexedAt     DATETIME;

CREATE VERTEX TYPE File IF NOT EXISTS EXTENDS GaosVertex BUCKETS 8;
CREATE PROPERTY File.path     STRING (mandatory true, notnull true);
CREATE PROPERTY File.checksum STRING;
CREATE PROPERTY File.language STRING;
CREATE PROPERTY File.loc      INTEGER (min 0);

CREATE VERTEX TYPE Function IF NOT EXISTS EXTENDS GaosVertex BUCKETS 8;
CREATE PROPERTY Function.name       STRING (mandatory true, notnull true);
CREATE PROPERTY Function.signature  STRING;
CREATE PROPERTY Function.startLine  INTEGER (min 0);
CREATE PROPERTY Function.complexity INTEGER (min 0);

CREATE VERTEX TYPE Commit IF NOT EXISTS EXTENDS GaosVertex;
CREATE PROPERTY Commit.sha         STRING (mandatory true, notnull true);
CREATE PROPERTY Commit.author      STRING;
CREATE PROPERTY Commit.message     STRING;
CREATE PROPERTY Commit.committedAt DATETIME;
